internal static partial class WideCorpus
{
    private static WideModule Quarry() => new("Quarry", "The depot aggregates invoice adjustments, meter readings and settlement previews. Amounts are whole minor units, usage and rates are nonnegative, and listed inputs keep arithmetic within signed 64-bit range. Integer shares truncate unless a rule specifies another method.",
    [
        Fault("MeterDebit", "long opening, long closing, long modulus, long reset, long preReset",
            "For a hardware reset, add the usage between opening and the final pre-reset reading to the new counter. Without reset the meter may roll at modulus. The pre-reset reading is at least opening.",
            "var span = closing - opening;\nif (span < 0) return modulus + span;\nreturn reset == 1 ? preReset - opening + closing : span;",
            "var span = closing - opening;\nif (reset == 1) return preReset - opening + closing;\nreturn span < 0 ? modulus + span : span;",
            [72, 11, 100, 0, 0], 39, [72, 11, 100, 1, 80], 19),
        Fault("UsageCharge", "long previous, long added, long included, long ceiling, long low, long high",
            "The first included units are free. The low band ends at absolute cycle volume ceiling, which is at least included. Return only the incremental charge introduced by added units.",
            "var start = Math.Max(previous - included, 0);\nvar end = Math.Max(previous + added - included, 0);\nlong Price(long usage) => Math.Min(usage, ceiling) * low + Math.Max(usage - ceiling, 0) * high;\nreturn Price(end) - Price(start);",
            "var start = Math.Max(previous - included, 0);\nvar end = Math.Max(previous + added - included, 0);\nvar band = ceiling - included;\nlong Price(long usage) => Math.Min(usage, band) * low + Math.Max(usage - band, 0) * high;\nreturn Price(end) - Price(start);",
            [1, 3, 2, 7, 2, 7], 4, [6, 3, 2, 7, 2, 7], 16),
        Fault("RefundSlice", "long invoice, long beforeRefund, long addedRefund, long refundableFee",
            "Return this refund's increment of the total reimbursable fee. The cumulative reimbursed fee is the truncated proportional fee. Refund totals never exceed invoice and invoice is positive.",
            "var available = invoice - beforeRefund;\nvar share = refundableFee * Math.Min(addedRefund, available) / invoice;\nreturn Math.Min(share, refundableFee - refundableFee * beforeRefund / invoice);",
            "var previous = refundableFee * beforeRefund / invoice;\nvar cumulative = refundableFee * (beforeRefund + addedRefund) / invoice;\nreturn cumulative - previous;",
            [20, 0, 10, 6], 3, [100, 20, 20, 3], 1),
        Fault("ConversionFee", "long amount, long numerator, long denominator, long feePermille, long minimum",
            "Convert into whole settlement cents with truncation. When converted cents meet minimum, the fee is the truncated permille of those whole cents. Denominator is positive.",
            "var gross = amount * numerator;\nvar settled = gross / denominator;\nif (settled < minimum) return 0;\nreturn gross * feePermille / (denominator * 1000);",
            "var settled = amount * numerator / denominator;\nreturn settled < minimum ? 0 : settled * feePermille / 1000;",
            [10, 1, 1, 500, 5], 5, [7, 4, 10, 750, 2], 1),
        Fault("DailyAccrual", "long start, long stop, long alreadyThrough, long period",
            "The partially filled first period is anchored at start. Charge the number of newly completed periods since alreadyThrough. Start is no later than alreadyThrough or stop. Period is positive.",
            "var next = Math.Max(alreadyThrough, start);\nvar elapsed = Math.Max(stop - next, 0);\nreturn elapsed / period;",
            "var previouslyComplete = (alreadyThrough - start) / period;\nvar totalComplete = (stop - start) / period;\nreturn Math.Max(totalComplete - previouslyComplete, 0);",
            [8, 32, 20, 6], 2, [8, 21, 13, 6], 2),
        Fault("Outstanding", "long principal, long tax, long credit, long taxEligible",
            "Credit can offset principal. It can also offset tax only with the taxEligible flag. Unused credit is retained for a later invoice. Return what is still owed now.",
            "var balance = principal + tax;\nvar limit = taxEligible == 1 ? balance : principal;\nreturn Math.Max(balance - Math.Min(credit, limit + tax), 0);",
            "var balance = principal + tax;\nvar limit = taxEligible == 1 ? balance : principal;\nreturn balance - Math.Min(credit, limit);",
            [100, 15, 20, 0], 95, [100, 15, 120, 0], 15),
        Fault("SalesTax", "long price, long discount, long freight, long rate, long freightTaxable",
            "Discount reduces merchandise down to zero. Taxable freight is then added to the base. Return tax at rate permille, rounded down.",
            "var gross = price + (freightTaxable == 1 ? freight : 0);\nvar payable = Math.Max(gross - discount, 0);\nreturn payable * rate / 1000;",
            "var merchandise = Math.Max(price - discount, 0);\nvar payable = merchandise + (freightTaxable == 1 ? freight : 0);\nreturn payable * rate / 1000;",
            [500, 100, 50, 200, 1], 90, [100, 200, 50, 200, 1], 10),
        Fault("RedeemVoucher", "long ordered, long submitted, long settled, long expiry, long cents",
            "The voucher window is reserved at the earliest submission on or after the order. Delayed settlement is allowed. A submission at expiry is too late. Return redeemed cents.",
            "var from = Math.Max(ordered, submitted);\nif (from >= expiry) return 0;\nreturn settled <= expiry ? cents : 0;",
            "var from = Math.Max(ordered, submitted);\nreturn from < expiry ? cents : 0;",
            [2, 4, 7, 10, 30], 30, [2, 4, 15, 10, 30], 30),
        Fault("VolumeRebate", "long baseUnits, long returns, long floor, long refundPerUnit, long cap",
            "Once net volume reaches floor, only net excess units qualify. Cap the rebate, with no charge when returns exceed base units.",
            "var net = Math.Max(baseUnits - returns, 0);\nif (net < floor) return 0;\nvar eligible = baseUnits - floor;\nreturn Math.Min(cap, eligible * refundPerUnit);",
            "var net = Math.Max(baseUnits - returns, 0);\nvar eligible = Math.Max(net - floor, 0);\nreturn Math.Min(cap, eligible * refundPerUnit);",
            [10, 0, 8, 2, 12], 4, [11, 2, 8, 2, 20], 2),
        Fault("DepositRelease", "long deposit, long damage, long waiver, long previouslyReleased, long inspected",
            "After inspection, waive the first waiver units of documented damage and withhold the remaining damage up to the original deposit. Only return what is still refundable after previous releases. Before inspection return zero.",
            "if (inspected == 0) return 0;\nvar reservable = Math.Min(deposit, damage);\nvar due = Math.Max(reservable - waiver, 0);\nreturn Math.Max(deposit - previouslyReleased - due, 0);",
            "if (inspected == 0) return 0;\nvar charge = Math.Max(damage - waiver, 0);\nvar due = Math.Min(deposit, charge);\nreturn Math.Max(deposit - previouslyReleased - due, 0);",
            [100, 30, 10, 20, 1], 60, [100, 170, 40, 10, 1], 0),
        Valid("RoundedLimit", "long units, long block", "Whole dispatch blocks are rounded up. An empty order needs no blocks. Block is positive.",
            "var whole = units / block;\nreturn whole + (units % block == 0 ? 0 : 1);", [11, 5], 3),
        Valid("RefundCap", "long requested, long fee, long consumed", "Use the remaining refundable balance. Consumed can exceed fee after an external correction; the remaining amount is then zero.",
            "var available = Math.Max(fee - consumed, 0);\nreturn Math.Min(available, requested);", [3, 10, 12], 0)
    ]);

    private static WideModule Juniper() => new("Juniper", "The local calendar service prepares recurring dispatch slots and summarizes reservations. Tick values may be signed where specified. Intermediates fit signed 64-bit arithmetic, and flags use 0 or 1.",
    [
        Fault("NextAppointment", "long now, long first, long firstFlex, long second, long secondFlex, long lead",
            "Choose visit 1 or 2 with the earliest feasible appointment. For each visit the proposed start is the later of its nominal time and now plus lead. It is feasible through its nominal time plus flex. Return zero if neither is feasible. Ties in proposed start prefer the earlier nominal time, then visit 1.",
            "var ready = now + lead;\nvar a = Math.Max(ready, first);\nvar b = Math.Max(ready, second);\nvar aOk = a <= first + firstFlex;\nvar bOk = b <= second + secondFlex;\nif (!aOk || !bOk) return aOk ? 1 : bOk ? 2 : 0;\nreturn a < b || a == b && firstFlex >= secondFlex ? 1 : 2;",
            "var ready = now + lead;\nvar a = Math.Max(ready, first);\nvar b = Math.Max(ready, second);\nvar aOk = a <= first + firstFlex;\nvar bOk = b <= second + secondFlex;\nif (!aOk || !bOk) return aOk ? 1 : bOk ? 2 : 0;\nreturn a < b || a == b && first <= second ? 1 : 2;",
            [2, 6, 2, 8, 3, 2], 1, [8, 6, 5, 7, 10, 2], 1),
        Fault("WeekSlot", "long day, long offset, long monthOrigin",
            "After adjusting by offset, group days into complete repeating seven-day weeks from monthOrigin. Return the day within the week, including for days earlier than origin.",
            "var relative = day - monthOrigin + offset;\nreturn Math.Abs(relative % 7);",
            "var relative = day - monthOrigin + offset;\nreturn (relative % 7 + 7) % 7;",
            [10, 2, 4], 1, [3, 0, 5], 5),
        Fault("QuietOverlap", "long open, long close, long quietOpen, long quietClose, long period",
            "Measure how much of one half-open reservation overlaps a single quiet interval in the same cycle. All arguments except period are offsets 0 through period minus one, and either interval may wrap. Equal endpoints mean empty.",
            "if (close < open) close += period;\nif (quietClose < quietOpen) quietClose += period;\nreturn Math.Max(0, Math.Min(close, quietClose) - Math.Max(open, quietOpen));",
            "if (close < open) close += period;\nif (quietClose < quietOpen) quietClose += period;\nlong Overlap(long shift) => Math.Max(0, Math.Min(close, quietClose + shift) - Math.Max(open, quietOpen + shift));\nreturn Overlap(-period) + Overlap(0) + Overlap(period);",
            [2, 8, 6, 9, 12], 2, [9, 3, 1, 4, 12], 2),
        Fault("NoticeCutoff", "long opens, long queued, long delivered, long lead, long paused",
            "The calendar uses active notification lead time. Subtract paused hours from time elapsed after the request was queued up to opening. Delivery after opening cannot satisfy the notice. Return 1 if the remaining lead meets the requirement.",
            "if (delivered > opens) return 0;\nvar effective = opens - Math.Max(queued + paused, delivered);\nreturn effective >= lead ? 1 : 0;",
            "if (delivered > opens) return 0;\nreturn opens - queued - paused >= lead ? 1 : 0;",
            [20, 6, 10, 8, 3], 1, [20, 6, 18, 6, 3], 1),
        Fault("ShiftEnd", "long localStart, long duration, long offsetStart, long offsetEnd",
            "Return local clock at end of a shift of duration real ticks. Offset is local minus global. The shift may cross an offset change.",
            "var globalStart = localStart - offsetStart;\nvar localDelta = duration + offsetStart;\nreturn globalStart + localDelta;",
            "var globalStart = localStart - offsetStart;\nreturn globalStart + duration + offsetEnd;",
            [8, 6, 2, 2], 14, [8, 6, 2, 1], 13),
        Fault("ConsolidatedEnd", "long firstStart, long firstEnd, long secondStart, long secondEnd, long thirdStart, long thirdEnd",
            "Return the ending tick of the consolidated reservation containing the first interval. Intervals are ordered by start. Touching intervals consolidate, including through an intermediate reservation.",
            "var end = firstEnd;\nif (secondStart <= firstEnd) end = Math.Max(end, secondEnd);\nif (thirdStart <= firstEnd) end = Math.Max(end, thirdEnd);\nreturn end;",
            "var end = firstEnd;\nif (secondStart <= end) end = Math.Max(end, secondEnd);\nif (thirdStart <= end) end = Math.Max(end, thirdEnd);\nreturn end;",
            [1, 6, 3, 7, 5, 9], 9, [1, 4, 3, 8, 7, 12], 12),
        Fault("ClockIncidence", "long from, long through, long eventAt, long switchedAt, long oldOffset, long newOffset",
            "Given a global event time and a global offset-change instant, test whether the event's converted local time belongs to the half-open interval from to through. Use the new offset at the transition.",
            "var converted = eventAt + oldOffset;\nvar local = converted >= switchedAt ? eventAt + newOffset : converted;\nreturn local >= from && local < through ? 1 : 0;",
            "var local = eventAt + (eventAt >= switchedAt ? newOffset : oldOffset);\nreturn local >= from && local < through ? 1 : 0;",
            [20, 32, 28, 20, 2, 3], 1, [19, 21, 18, 20, 2, 3], 1),
        Fault("RevisionInterval", "long lower, long upper, long initialAt, long amendmentAt, long queryAt",
            "A reservation is usable within its half-open lower/upper bounds only after initialAt. An amendment adds no suspension before its own time and affects details only. Return 1 when the reservation is usable.",
            "var effective = Math.Max(initialAt, amendmentAt);\nreturn queryAt >= effective && queryAt >= lower && queryAt < upper ? 1 : 0;",
            "return queryAt >= initialAt && queryAt >= lower && queryAt < upper ? 1 : 0;",
            [5, 30, 2, 8, 15], 1, [5, 30, 2, 18, 10], 1),
        Fault("BatchCadence", "long stagedAt, long allowed, long phase, long period",
            "Choose the earliest scheduled boundary no earlier than both stagedAt and allowed. Boundary times are phase plus a nonnegative multiple of period. All times are nonnegative and period is positive.",
            "var start = Math.Max(stagedAt, allowed);\nvar span = Math.Max(start - phase, 0);\nvar next = (span + period) / period;\nreturn phase + next * period;",
            "var start = Math.Max(stagedAt, allowed);\nvar span = Math.Max(start - phase, 0);\nvar next = span / period + (span % period == 0 ? 0 : 1);\nreturn phase + next * period;",
            [8, 7, 3, 4], 11, [7, 5, 3, 4], 7),
        Fault("BlackoutBudget", "long start, long finish, long freezeStart, long freezeEnd, long held",
            "Start through finish is the requested interval. Subtract its intersection with the blackout, then subtract held work, clamping remaining budget to zero. All intervals are ordered.",
            "var duration = finish - start;\nif (freezeEnd <= start || freezeStart >= finish) return Math.Max(duration - held, 0);\nreturn Math.Max(duration - (freezeEnd - freezeStart) - held, 0);",
            "var duration = finish - start;\nvar overlap = Math.Max(0, Math.Min(finish, freezeEnd) - Math.Max(start, freezeStart));\nreturn Math.Max(duration - overlap - held, 0);",
            [10, 30, 14, 19, 4], 11, [10, 30, 6, 14, 3], 13),
        Valid("Midpoint", "long low, long high", "The midpoint of nonnegative ordered bounds rounds toward low. Bounds can be large enough that low plus high overflows.",
            "return low + (high - low) / 2;", [10, 15], 12),
        Valid("InclusiveTicks", "long first, long last", "Count inclusive ticks in an ordered or empty interval. Equal endpoints denote one tick.",
            "return last < first ? 0 : last - first + 1;", [7, 7], 1)
    ]);
}
